· Tarifa 1B · Medidor REM833 · Fecha límite aproximada"}, {"tipo": "renta", "concepto": "Renta", "proveedor": "JUAN MARIANO RAFAEL SALAZAR", "cuenta": null, "periodicidad": "mensual", "fecha": "2026-12-08", "notas": "Banco: BANREGIO · Paga: 8 DE CADA MES"}], "fecha_cierre": "2027-01-21", "fecha_apertura": "2026-01-21"}, {"nombre": "NF- CASA TIJUANA MANRIQUEZ", "empresa": "grupo firme de m", "tipo": "campamento", "municipio": "Tijuana", "estado": "Baja California", "cc": null, "telefono": null, "calle": null, "situacion": null, "observaciones": "Cargado del archivo SERVICIOS v2 (nov 2026)", "servicios": [], "fecha_cierre": null, "fecha_apertura": null}]'::jsonb) loop
    select id into v_emp from public.empresas where activo and nombre ilike '%' || (x->>'empresa') || '%' order by nombre limit 1;
    if v_emp is null then raise exception 'No encontré la empresa % para %', x->>'empresa', x->>'nombre'; end if;
    if exists (select 1 from public.inmuebles where empresa_id = v_emp and upper(nombre) = upper(x->>'nombre') and activo) then n_skip := n_skip + 1; continue; end if;
    v_cc := null;
    if x->>'cc' is not null then
      select id into v_cc from public.centros_costo where upper(clave) = upper(x->>'cc') order by (empresa_id = v_emp) desc limit 1;
    end if;
    insert into public.inmuebles (empresa_id, nombre, tipo, municipio, estado, calle, telefono, situacion, observaciones, obra_cc_id, estatus_operacion, fecha_apertura, fecha_cierre, clasificacion)
    values (v_emp, x->>'nombre', x->>'tipo', x->>'municipio', coalesce(x->>'estado', 'Baja California Sur'), x->>'calle', x->>'telefono', x->>'situacion',
            x->>'observaciones' || case when x->>'cc' is not null and v_cc is null then E'\nCC ' || (x->>'cc') || ' no encontrado en el catálogo' else '' end,
            v_cc, 'operando', (x->>'fecha_apertura')::date, (x->>'fecha_cierre')::date, 'urbana')
    returning id into v_id;
    n_inm := n_inm + 1;
    for s in select * from jsonb_array_elements(x->'servicios') loop
      insert into public.inmueble_pagos (inmueble_id, empresa_id, tipo, concepto, proveedor, cuenta, periodicidad, fecha_limite, notas)
      values (v_id, v_emp, s->>'tipo', s->>'concepto', s->>'proveedor', s->>'cuenta', s->>'periodicidad', (s->>'fecha')::date, s->>'notas');
      n_serv := n_serv + 1;
    end loop;
  end loop;
  raise notice 'Inmuebles: %, servicios: %, ya existían: %', n_inm, n_serv, n_skip;
end $$;

select tipo, count(*) as inmuebles, (select count(*) from public.inmueble_pagos p join public.inmuebles i2 on i2.id = p.inmueble_id where i2.tipo = i.tipo and i2.observaciones like '%SERVICIOS v2%') as servicios
from public.inmuebles i where observaciones like '%SERVICIOS v2%' group by tipo;
